#[test]
fn check_build_run_and_test_accept_deno_env_set_in_js_input() {
    let dir = tempdir().expect("tempdir");
    let source_path = dir.path().join("main.js");
    fs::write(
        &source_path,
        "Deno.env.set('KALI_ENV_SET_SMOKE', 'hello-environment');\nconsole.log(Deno.env.get('KALI_ENV_SET_SMOKE'));\n",
    )
    .expect("write source");

    for command in ["check", "build"] {
        let output = Command::new(kali_bin())
            .current_dir(dir.path())
            .arg(command)
            .arg("--api")
            .arg("deno")
            .arg(&source_path)
            .output()
            .expect("run kali");

        assert!(output.status.success(), "{command} failed: {:?}", output);
    }

    let output = Command::new(kali_bin())
        .current_dir(dir.path())
        .arg("run")
        .arg("--api")
        .arg("deno")
        .arg(&source_path)
        .output()
        .expect("run kali");

    assert!(output.status.success(), "run failed: {:?}", output);
    let stdout = String::from_utf8_lossy(&output.stdout);
    assert_eq!(stdout.trim(), "hello-environment", "stdout: {stdout}");

    let test_path = dir.path().join("smoke.test.js");
    fs::write(
        &test_path,
        "Deno.env.set('KALI_ENV_SET_SMOKE', 'hello-environment');\nKali.test('env mutation', () => { if (Deno.env.get('KALI_ENV_SET_SMOKE') !== 'hello-environment') { throw new Error('expected env mutation'); } });\n",
    )
    .expect("write test source");

    let output = Command::new(kali_bin())
        .current_dir(dir.path())
        .arg("test")
        .arg("--api")
        .arg("deno")
        .arg(&test_path)
        .output()
        .expect("run kali");

    assert!(output.status.success(), "test failed: {:?}", output);
    let stdout = String::from_utf8_lossy(&output.stdout);
    assert!(stdout.contains("ok 1"), "stdout: {stdout}");
}

#[test]
fn json_check_build_run_and_test_accept_deno_env_set_in_js_input() {
    let dir = tempdir().expect("tempdir");
    let source_path = dir.path().join("main.js");
    fs::write(
        &source_path,
        "Deno.env.set('KALI_ENV_SET_SMOKE', 'hello-environment');\nconsole.log(Deno.env.get('KALI_ENV_SET_SMOKE'));\n",
    )
    .expect("write source");

    for command in ["check", "build"] {
        let output = Command::new(kali_bin())
            .current_dir(dir.path())
            .arg("--output")
            .arg("json")
            .arg(command)
            .arg("--api")
            .arg("deno")
            .arg(&source_path)
            .output()
            .expect("run kali");

        assert!(
            output.status.success(),
            "{command} failed: stdout: {} stderr: {}",
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        );
        let json = parse_json_stdout(&output);
        assert_eq!(json["schemaVersion"], 1);
        assert_eq!(json["command"], command);
        assert_eq!(json["success"], true);
        assert_eq!(json["exitCode"], 0);
        match command {
            "check" => {
                assert_eq!(json["payload"]["filesChecked"], 1);
                assert!(json["errors"].as_array().expect("errors array").is_empty());
            }
            "build" => {
                let payload = json["payload"].as_object().expect("build payload object");
                assert_eq!(payload["artifactKind"], "executable");
                assert_eq!(payload["buildMode"], "fast");
                let output_path =
                    PathBuf::from(payload["outputPath"].as_str().expect("output path"));
                assert_eq!(output_path, source_path.with_extension("wasm"));
                assert!(
                    output_path.exists(),
                    "expected build artifact at {output_path:?}"
                );
                assert!(payload["sizeBytes"].as_u64().expect("size bytes") > 0);
                assert!(payload["sourceHash"].as_str().is_some());
            }
            _ => unreachable!("unexpected command {command}"),
        }
    }

    let output = Command::new(kali_bin())
        .current_dir(dir.path())
        .arg("--output")
        .arg("json")
        .arg("run")
        .arg("--api")
        .arg("deno")
        .arg(&source_path)
        .output()
        .expect("run kali");

    assert!(
        output.status.success(),
        "stdout: {}\nstderr: {}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let json = parse_json_stdout(&output);
    assert_eq!(json["schemaVersion"], 1);
    assert_eq!(json["command"], "run");
    assert_eq!(json["success"], true);
    assert_eq!(json["exitCode"], 0);
    assert_eq!(json["payload"]["exitCode"], 0);
    assert_eq!(json["payload"]["hostContract"], "kali-hosted");
    assert_eq!(json["payload"]["runtimeBackend"], "wasmtime");
    assert_eq!(json["stdout"], "hello-environment\n");
    assert_eq!(json["stderr"], "");

    let test_path = dir.path().join("smoke.test.js");
    fs::write(
        &test_path,
        "Deno.env.set('KALI_ENV_SET_SMOKE', 'hello-environment');\nKali.test('env mutation', () => { if (Deno.env.get('KALI_ENV_SET_SMOKE') !== 'hello-environment') { throw new Error('expected env mutation'); } });\n",
    )
    .expect("write test source");

    let output = Command::new(kali_bin())
        .current_dir(dir.path())
        .arg("--output")
        .arg("json")
        .arg("test")
        .arg("--api")
        .arg("deno")
        .arg(&test_path)
        .output()
        .expect("run kali");

    assert!(
        output.status.success(),
        "stdout: {}\nstderr: {}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let json = parse_json_stdout(&output);
    assert_eq!(json["schemaVersion"], 1);
    assert_eq!(json["command"], "test");
    assert_eq!(json["success"], true);
    assert_eq!(json["exitCode"], 0);
    assert_eq!(json["payload"]["total"], 1);
    assert_eq!(json["payload"]["passed"], 1);
    assert_eq!(json["payload"]["failed"], 0);
    assert_eq!(json["payload"]["skipped"], 0);
    assert_eq!(json["payload"]["hostContract"], "kali-hosted");
    assert_eq!(json["payload"]["runtimeBackend"], "wasmtime");
    assert_eq!(json["stdout"], "");
    assert_eq!(json["stderr"], "");
}

