#[test]
fn build_rejects_multiple_source_files() {
    let dir = tempdir().expect("tempdir");
    let source_path = dir.path().join("main.ts");
    let extra_path = dir.path().join("extra.ts");
    fs::write(&source_path, "console.log(1);").expect("write source");
    fs::write(&extra_path, "console.log(2);").expect("write extra source");

    let output = Command::new(kali_bin())
        .current_dir(dir.path())
        .arg("build")
        .arg(&source_path)
        .arg(&extra_path)
        .output()
        .expect("run kali");

    assert!(!output.status.success());
    assert_eq!(output.status.code(), Some(5));
    let stderr = String::from_utf8_lossy(&output.stderr);
    assert!(stderr.contains("E5508"), "stderr: {stderr}");
    assert!(
        stderr.contains("only one primary source file"),
        "stderr: {stderr}"
    );
    assert!(!dir.path().join("main.wasm").exists());
}

#[test]
fn json_init_emits_a_command_envelope() {
    let dir = tempdir().expect("tempdir");

    let output = Command::new(kali_bin())
        .current_dir(dir.path())
        .arg("--output")
        .arg("json")
        .arg("init")
        .output()
        .expect("run kali");

    assert!(
        output.status.success(),
        "stderr: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    let json = parse_json_stdout(&output);
    let root = dir.path().to_string_lossy().into_owned();
    let manifest_path = dir.path().join("kali.json").to_string_lossy().into_owned();
    let source_path = dir.path().join("main.ts").to_string_lossy().into_owned();
    assert_eq!(json["schemaVersion"], 1);
    assert_eq!(json["command"], "init");
    assert_eq!(json["success"], true);
    assert_eq!(json["payload"]["root"], root);
    assert_eq!(json["payload"]["manifestPath"], manifest_path);
    assert_eq!(json["payload"]["sourcePath"], source_path);
    assert_eq!(json["payload"]["library"], false);
    assert_eq!(json["exitCode"], 0);
}

